class Car:
    def __init__(self, model, color):
        self.model = model  # атрибут
        self.color = color

    def drive(self):
        print(f"{self.model} едет...")

my_car = Car("Nexia", "Белый") # создание объекта
my_car.drive()

class Animal:
    def make_sound(self):
        print("Звук...")

class Dog(Animal):  # унаследован от Animal
    def make_sound(self):  # полиморфизм (переопределение метода)
        print("Гав-гав")

dog = Dog()
dog.make_sound() # Гав-гав

